/**
 * Simulated end-to-end test for the pi-posthog extension.
 *
 * Boots a mock PostHog ingestion server on localhost, drives the real
 * extension through a realistic pi session (two LLM calls, one tool call),
 * and asserts on the captured $ai_* events. No network, no pi binary, no
 * API keys required.
 *
 * Run: node test/simulate.ts   (Node ≥ 23.6 — native TypeScript stripping)
 */
import assert from "node:assert/strict";
import http from "node:http";
import type { AddressInfo } from "node:net";
import factory from "../extensions/posthog.ts";

// ---------------------------------------------------------------------------
// Mock PostHog server
// ---------------------------------------------------------------------------

interface CapturedEvent {
	event: string;
	distinct_id: string;
	properties: Record<string, any>;
	timestamp: string;
	uuid: string;
}

let received: CapturedEvent[] = [];

const server = http.createServer((req, res) => {
	const chunks: Buffer[] = [];
	req.on("data", (c) => chunks.push(c));
	req.on("end", () => {
		if (req.url?.startsWith("/batch")) {
			const body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
			received.push(...body.batch);
		}
		res.writeHead(200, { "Content-Type": "application/json" });
		res.end('{"status":1}');
	});
});

await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = (server.address() as AddressInfo).port;

// ---------------------------------------------------------------------------
// Fake pi harness
// ---------------------------------------------------------------------------

function makeFakePi() {
	const handlers = new Map<string, Array<(event: any, ctx: any) => Promise<any> | any>>();
	const commands = new Map<string, any>();
	const pi: any = {
		on(event: string, handler: any) {
			if (!handlers.has(event)) handlers.set(event, []);
			handlers.get(event)!.push(handler);
		},
		registerCommand(name: string, options: any) {
			commands.set(name, options);
		},
		getAllTools: () => [{ name: "bash", description: "Run a shell command", parameters: {} }],
		getActiveTools: () => ["bash"],
		getThinkingLevel: () => "high",
		registerTool() {},
		registerShortcut() {},
		registerFlag() {},
		getFlag: () => undefined,
		registerMessageRenderer() {},
		sendMessage() {},
		sendUserMessage() {},
		appendEntry() {},
		setSessionName() {},
		getSessionName: () => undefined,
		setLabel() {},
		exec: async () => ({ stdout: "", stderr: "", code: 0, killed: false }),
		setActiveTools() {},
		getCommands: () => [],
		setModel: async () => true,
		setThinkingLevel() {},
		registerProvider() {},
		unregisterProvider() {},
		events: { on() {}, emit() {} },
	};
	return { pi, handlers, commands };
}

const ctx: any = {
	ui: {
		notify() {},
		setStatus() {},
	},
	hasUI: false,
	mode: "print",
	cwd: process.cwd(),
	sessionManager: { getSessionId: () => "sess-test-123" },
	modelRegistry: {},
	model: { id: "claude-opus-4-5", baseUrl: "https://api.anthropic.com", provider: "anthropic" },
	isIdle: () => true,
	isProjectTrusted: () => true,
	signal: undefined,
	abort() {},
	hasPendingMessages: () => false,
	shutdown() {},
	getContextUsage: () => undefined,
	compact() {},
	getSystemPrompt: () => "You are pi, a coding agent.",
};

async function emit(handlers: Map<string, any[]>, type: string, event: any) {
	for (const handler of handlers.get(type) ?? []) {
		await handler({ type, ...event }, ctx);
	}
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

const userMessage = { role: "user", content: "Please list the files here", timestamp: 1 };

const assistant1 = {
	role: "assistant",
	content: [
		{ type: "thinking", thinking: "secret chain of thought" },
		{ type: "text", text: "Let me check the directory." },
		{ type: "toolCall", id: "tc_1", name: "bash", arguments: { command: "ls -la" } },
	],
	api: "anthropic-messages",
	provider: "anthropic",
	model: "claude-opus-4-5",
	usage: {
		input: 1200,
		output: 80,
		cacheRead: 300,
		cacheWrite: 100,
		totalTokens: 1680,
		cost: { input: 0.0036, output: 0.0012, cacheRead: 0.00009, cacheWrite: 0.000375, total: 0.005265 },
	},
	stopReason: "toolUse",
	timestamp: 2,
};

const toolResultMessage = {
	role: "toolResult",
	toolCallId: "tc_1",
	toolName: "bash",
	content: [{ type: "text", text: "file-a\nfile-b" }],
	isError: false,
	timestamp: 3,
};

const assistant2 = {
	role: "assistant",
	content: [{ type: "text", text: "All done — 2 files found." }],
	api: "anthropic-messages",
	provider: "anthropic",
	model: "claude-opus-4-5",
	usage: {
		input: 1400,
		output: 40,
		cacheRead: 1200,
		cacheWrite: 0,
		totalTokens: 1440,
		cost: { input: 0.0042, output: 0.0006, cacheRead: 0.00036, cacheWrite: 0, total: 0.00516 },
	},
	stopReason: "stop",
	timestamp: 4,
};

// ---------------------------------------------------------------------------
// Run 1: full capture
// ---------------------------------------------------------------------------

process.env.PI_POSTHOG_API_KEY = "[REDACTED]";
process.env.PI_POSTHOG_HOST = `http://127.0.0.1:${port}`;
process.env.PI_POSTHOG_DISTINCT_ID = "pi-test-user";
delete process.env.PI_POSTHOG_CAPTURE_CONTENT;
delete process.env.PI_POSTHOG_DISABLED;

{
	const { pi, handlers } = makeFakePi();
	factory(pi);

	await emit(handlers, "session_start", { reason: "startup" });
	await emit(handlers, "before_agent_start", { prompt: "Please list the files here", systemPrompt: "x", systemPromptOptions: {} });
	await emit(handlers, "agent_start", {});

	// turn 0: assistant decides to call a tool
	await emit(handlers, "context", { messages: [userMessage] });
	await emit(handlers, "turn_start", { turnIndex: 0, timestamp: Date.now() });
	await emit(handlers, "after_provider_response", { status: 200, headers: {} });
	await emit(handlers, "message_start", { message: { role: "assistant", content: [] } });
	await sleep(5);
	await emit(handlers, "message_update", { message: assistant1, assistantMessageEvent: { type: "text_start", contentIndex: 0, partial: assistant1 } });
	await emit(handlers, "message_end", { message: assistant1 });
	await emit(handlers, "tool_execution_start", { toolCallId: "tc_1", toolName: "bash", args: { command: "ls -la" } });
	await sleep(5);
	await emit(handlers, "tool_execution_end", {
		toolCallId: "tc_1",
		toolName: "bash",
		result: { content: [{ type: "text", text: "file-a\nfile-b" }], details: {} },
		isError: false,
	});
	await emit(handlers, "turn_end", { turnIndex: 0, message: assistant1, toolResults: [toolResultMessage] });

	// turn 1: final answer
	await emit(handlers, "context", { messages: [userMessage, assistant1, toolResultMessage] });
	await emit(handlers, "turn_start", { turnIndex: 1, timestamp: Date.now() });
	await emit(handlers, "after_provider_response", { status: 200, headers: {} });
	await emit(handlers, "message_start", { message: { role: "assistant", content: [] } });
	await emit(handlers, "message_update", { message: assistant2, assistantMessageEvent: { type: "text_start", contentIndex: 0, partial: assistant2 } });
	await emit(handlers, "message_end", { message: assistant2 });
	await emit(handlers, "turn_end", { turnIndex: 1, message: assistant2, toolResults: [] });

	await emit(handlers, "agent_end", { messages: [userMessage, assistant1, toolResultMessage, assistant2] });
	await emit(handlers, "session_shutdown", { reason: "quit" });
}

// ---- assertions ------------------------------------------------------------

const generations = received.filter((e) => e.event === "$ai_generation");
const spans = received.filter((e) => e.event === "$ai_span");
const traces = received.filter((e) => e.event === "$ai_trace");

assert.equal(generations.length, 2, "expected 2 $ai_generation events");
assert.equal(spans.length, 1, "expected 1 $ai_span event");
assert.equal(traces.length, 1, "expected 1 $ai_trace event");

const [gen1, gen2] = generations;
const span = spans[0];
const trace = traces[0];
const traceId = trace.properties.$ai_trace_id;

// identity + linkage
assert.equal(trace.distinct_id, "pi-test-user");
assert.ok(traceId, "trace id present");
assert.equal(gen1.properties.$ai_trace_id, traceId);
assert.equal(gen2.properties.$ai_trace_id, traceId);
assert.equal(gen1.properties.$ai_parent_id, traceId);
assert.equal(span.properties.$ai_trace_id, traceId);
assert.equal(span.properties.$ai_parent_id, gen1.properties.$ai_span_id, "tool span nests under generation 1");
assert.equal(span.properties.$ai_span_id, "tc_1");
for (const e of [gen1, gen2, span, trace]) {
	assert.equal(e.properties.$ai_session_id, "sess-test-123");
	assert.equal(e.properties.$lib, "pi-posthog");
}

// generation 1: model, tokens, cost passthrough
assert.equal(gen1.properties.$ai_model, "claude-opus-4-5");
assert.equal(gen1.properties.$ai_provider, "anthropic");
assert.equal(gen1.properties.$ai_base_url, "https://api.anthropic.com");
assert.equal(gen1.properties.$ai_input_tokens, 1200);
assert.equal(gen1.properties.$ai_output_tokens, 80);
assert.equal(gen1.properties.$ai_cache_read_input_tokens, 300);
assert.equal(gen1.properties.$ai_cache_creation_input_tokens, 100);
assert.equal(gen1.properties.$ai_cache_reporting_exclusive, true);
assert.equal(gen1.properties.$ai_http_status, 200);
assert.equal(gen1.properties.$ai_stop_reason, "toolUse");
assert.equal(gen1.properties.$ai_span_name, "turn 0");
assert.ok(Math.abs(gen1.properties.$ai_input_cost_usd - 0.004065) < 1e-9, "input cost = input+cacheRead+cacheWrite");
assert.ok(Math.abs(gen1.properties.$ai_output_cost_usd - 0.0012) < 1e-9);
assert.ok(Math.abs(gen1.properties.$ai_total_cost_usd - 0.005265) < 1e-9);
assert.equal(typeof gen1.properties.$ai_latency, "number");
assert.equal(typeof gen1.properties.$ai_time_to_first_token, "number");
assert.ok(gen1.properties.$ai_latency >= gen1.properties.$ai_time_to_first_token);
assert.equal(gen1.properties.$ai_model_parameters.thinking_level, "high");

// content capture
const input1 = gen1.properties.$ai_input;
assert.ok(Array.isArray(input1) && input1.length === 1);
assert.equal(input1[0].role, "user");
assert.match(input1[0].content, /list the files/);
const output1 = gen1.properties.$ai_output_choices[0];
assert.equal(output1.role, "assistant");
assert.match(output1.content, /Let me check/);
assert.ok(!JSON.stringify(output1).includes("secret chain of thought"), "thinking redacted by default");
assert.equal(output1.tool_calls[0].function.name, "bash");
const input2 = gen2.properties.$ai_input;
assert.equal(input2.length, 3);
assert.equal(input2[1].role, "assistant");
assert.equal(input2[2].role, "tool");
assert.match(input2[2].content, /file-a/);

// tools metadata
assert.equal(gen1.properties.$ai_tools[0].function.name, "bash");

// tool span
assert.equal(span.properties.$ai_span_name, "bash");
assert.equal(span.properties.$ai_span_type, "tool");
assert.deepEqual(span.properties.$ai_input_state, { command: "ls -la" });
assert.match(span.properties.$ai_output_state, /file-a/);
assert.equal(typeof span.properties.$ai_latency, "number");
assert.ok(span.properties.$ai_latency > 0);
assert.ok(!("$ai_is_error" in span.properties));

// trace
assert.equal(trace.properties.$ai_span_name, "Please list the files here");
assert.equal(trace.properties.pi_turns, 2);
assert.equal(trace.properties.pi_generations, 2);
assert.equal(trace.properties.pi_tool_calls, 1);
assert.equal(trace.properties.pi_model, "claude-opus-4-5");
assert.match(trace.properties.$ai_output_state[0].content, /All done/);
assert.equal(typeof trace.properties.$ai_latency, "number");

console.log(`✓ run 1 (full capture): ${received.length} events, all assertions passed`);

// ---------------------------------------------------------------------------
// Run 2: content capture disabled
// ---------------------------------------------------------------------------

received = [];
process.env.PI_POSTHOG_CAPTURE_CONTENT = "0";

{
	const { pi, handlers } = makeFakePi();
	factory(pi);
	await emit(handlers, "session_start", { reason: "startup" });
	await emit(handlers, "before_agent_start", { prompt: "secret prompt", systemPrompt: "x", systemPromptOptions: {} });
	await emit(handlers, "agent_start", {});
	await emit(handlers, "context", { messages: [{ role: "user", content: "secret prompt", timestamp: 1 }] });
	await emit(handlers, "turn_start", { turnIndex: 0, timestamp: Date.now() });
	await emit(handlers, "message_start", { message: { role: "assistant", content: [] } });
	await emit(handlers, "message_end", { message: assistant2 });
	await emit(handlers, "agent_end", { messages: [assistant2] });
	await emit(handlers, "session_shutdown", { reason: "quit" });
}

const redactedGen = received.find((e) => e.event === "$ai_generation");
const redactedTrace = received.find((e) => e.event === "$ai_trace");
assert.ok(redactedGen && redactedTrace);
assert.ok(!("$ai_input" in redactedGen.properties), "no $ai_input when content capture is off");
assert.ok(!("$ai_output_choices" in redactedGen.properties));
assert.ok(!("$ai_input_state" in redactedTrace.properties));
assert.ok(!("$ai_output_state" in redactedTrace.properties));
assert.equal(redactedGen.properties.$ai_input_tokens, 1400, "tokens still captured");
assert.ok(!JSON.stringify(received).includes("secret prompt"), "prompt text never leaves the process");

console.log(`✓ run 2 (content capture off): redaction verified`);

server.close();
console.log("ALL TESTS PASSED");

/**
 * pi-posthog — PostHog LLM analytics for the pi coding agent.
 *
 * Streams pi's agent lifecycle into PostHog's LLM analytics (AI observability)
 * product using the native $ai_* event schema:
 *
 *   pi session          → $ai_session_id (groups traces into a conversation)
 *   one prompt → run    → one trace, closed with an $ai_trace event
 *   each LLM call       → $ai_generation (model, tokens, cost, latency, content)
 *   each tool execution → $ai_span (type "tool", nested under the generation
 *                         that issued the tool call)
 *   context compaction  → $ai_span (type "compaction")
 *
 * Zero runtime dependencies — a single file you can drop into
 * ~/.pi/agent/extensions/ or install as a pi package.
 *
 * Configuration (env vars override config files):
 *   PI_POSTHOG_API_KEY / POSTHOG_API_KEY   project API key (phc_…)  [required]
 *   PI_POSTHOG_HOST / POSTHOG_HOST         default https://us.i.posthog.com
 *   PI_POSTHOG_DISTINCT_ID                 default "pi:<user>@<host>"
 *   PI_POSTHOG_CAPTURE_CONTENT=0           redact prompts/completions/tool IO
 *   PI_POSTHOG_DEBUG=1                     log to ~/.pi/agent/posthog-debug.log
 *   PI_POSTHOG_DISABLED=1                  turn the extension off
 *
 * Config files (deep-merged, project wins): ~/.pi/agent/posthog.json and
 * .pi/posthog.json — see PosthogConfig for all keys.
 */

import { randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import type { AssistantMessage } from "@earendil-works/pi-ai";

const LIB_NAME = "pi-posthog";
const LIB_VERSION = "0.1.0";

/** Per-message content cap inside $ai_input / $ai_output_choices. */
const MAX_MESSAGE_CHARS = 8_000;
/** Max messages kept in $ai_input (head + tail are preserved). */
const MAX_INPUT_MESSAGES = 40;
/** Cap for $ai_input_state / $ai_output_state on spans. */
const MAX_STATE_CHARS = 20_000;
/** Cap for serialized tool_call arguments. */
const MAX_TOOL_ARG_CHARS = 4_000;
/** Hard cap on a single event's JSON size; heavy props are dropped beyond it. */
const MAX_EVENT_JSON_CHARS = 400_000;

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

interface PosthogConfig {
	/** PostHog project API key (phc_…). Without it the extension is inert. */
	apiKey?: string;
	/** Ingestion host. https://us.i.posthog.com or https://eu.i.posthog.com. */
	host: string;
	/** Person the events are attributed to. Default: pi:<os user>@<hostname>. */
	distinctId?: string;
	/** Capture prompts, completions and tool inputs/outputs. Default true. */
	captureContent: boolean;
	/** Include model thinking blocks in captured output. Default false. */
	captureThinking: boolean;
	/** Prepend a (truncated) system prompt message to $ai_input. Default false. */
	captureSystemPrompt: boolean;
	/** Attach active tool names/descriptions as $ai_tools. Default true. */
	captureTools: boolean;
	/** Show a "posthog" counter in the pi status bar. Default true. */
	statusBar: boolean;
	enabled: boolean;
	debug: boolean;
	flushAt: number;
	flushIntervalMs: number;
	maxQueueSize: number;
}

const DEFAULT_CONFIG: PosthogConfig = {
	host: "https://us.i.posthog.com",
	captureContent: true,
	captureThinking: false,
	captureSystemPrompt: false,
	captureTools: true,
	statusBar: true,
	enabled: true,
	debug: false,
	flushAt: 20,
	flushIntervalMs: 3_000,
	maxQueueSize: 1_000,
};

function envBool(value: string | undefined): boolean | undefined {
	if (value === undefined) return undefined;
	return !["0", "false", "off", "no", ""].includes(value.toLowerCase());
}

function readJsonFile(filePath: string): Partial<PosthogConfig> | undefined {
	try {
		if (!fs.existsSync(filePath)) return undefined;
		return JSON.parse(fs.readFileSync(filePath, "utf8")) as Partial<PosthogConfig>;
	} catch {
		return undefined;
	}
}

function loadConfig(cwd: string): PosthogConfig {
	const userFile = readJsonFile(path.join(os.homedir(), ".pi", "agent", "posthog.json"));
	const projectFile = readJsonFile(path.join(cwd, ".pi", "posthog.json"));
	const env = process.env;
	const merged: PosthogConfig = {
		...DEFAULT_CONFIG,
		...userFile,
		...projectFile,
	};
	merged.apiKey = [REDACTED] ?? env.POSTHOG_API_KEY ?? merged.apiKey;
	merged.host = env.PI_POSTHOG_HOST ?? env.POSTHOG_HOST ?? merged.host;
	merged.distinctId = env.PI_POSTHOG_DISTINCT_ID ?? merged.distinctId;
	merged.captureContent = envBool(env.PI_POSTHOG_CAPTURE_CONTENT) ?? merged.captureContent;
	merged.debug = envBool(env.PI_POSTHOG_DEBUG) ?? merged.debug;
	if (envBool(env.PI_POSTHOG_DISABLED)) merged.enabled = false;
	merged.host = merged.host.replace(/\/+$/, "");
	return merged;
}

function defaultDistinctId(): string {
	let user = "unknown";
	try {
		user = os.userInfo().username;
	} catch {
		/* e.g. no passwd entry */
	}
	return `pi:${user}@${os.hostname()}`;
}

// ---------------------------------------------------------------------------
// Minimal PostHog capture client (batching, retries, no dependencies)
// ---------------------------------------------------------------------------

interface QueuedEvent {
	event: string;
	distinct_id: string;
	properties: Record<string, unknown>;
	timestamp: string;
	uuid: string;
}

class PostHogClient {
	sent = 0;
	dropped = 0;
	lastError: string | undefined;
	private queue: QueuedEvent[] = [];
	private timer: ReturnType<typeof setTimeout> | undefined;
	private inflight: Promise<void> | undefined;
	private cfg: PosthogConfig;
	private log: (message: string) => void;

	constructor(cfg: PosthogConfig, log: (message: string) => void) {
		this.cfg = cfg;
		this.log = log;
	}

	get queued(): number {
		return this.queue.length;
	}

	capture(event: string, distinctId: string, properties: Record<string, unknown>): void {
		if (this.queue.length >= this.cfg.maxQueueSize) {
			this.queue.shift();
			this.dropped++;
		}
		this.queue.push({
			event,
			distinct_id: distinctId,
			properties,
			timestamp: new Date().toISOString(),
			uuid: randomUUID(),
		});
		this.log(`queued ${event} (${this.queue.length} pending)`);
		if (this.queue.length >= this.cfg.flushAt) {
			void this.flush();
		} else {
			this.schedule();
		}
	}

	private schedule(): void {
		if (this.timer) return;
		this.timer = setTimeout(() => {
			this.timer = undefined;
			void this.flush();
		}, this.cfg.flushIntervalMs);
		// Never keep the pi process alive just for analytics.
		this.timer.unref?.();
	}

	async flush(): Promise<void> {
		while (this.inflight) await this.inflight;
		if (this.queue.length === 0) return;
		this.inflight = this.drain();
		try {
			await this.inflight;
		} finally {
			this.inflight = undefined;
		}
	}

	private async drain(): Promise<void> {
		while (this.queue.length > 0) {
			const batch = this.queue.splice(0, 50);
			const delivered = await this.send(batch);
			if (!delivered) {
				// Transient failure: requeue and give up until the next flush.
				this.queue.unshift(...batch);
				if (this.queue.length > this.cfg.maxQueueSize) {
					this.dropped += this.queue.length - this.cfg.maxQueueSize;
					this.queue.length = this.cfg.maxQueueSize;
				}
				return;
			}
		}
	}

	/** True when the batch is settled (delivered or permanently rejected). */
	private async send(batch: QueuedEvent[]): Promise<boolean> {
		const body = JSON.stringify({ api_key: [REDACTED], batch });
		for (let attempt = 0; attempt < 2; attempt++) {
			try {
				const res = await fetch(`${this.cfg.host}/batch/`, {
					method: "POST",
					headers: { "Content-Type": "application/json" },
					body,
					signal: AbortSignal.timeout(10_000),
				});
				if (res.ok) {
					this.sent += batch.length;
					this.lastError = undefined;
					this.log(`flushed ${batch.length} events`);
					return true;
				}
				this.lastError = `HTTP ${res.status}`;
				this.log(`flush failed: HTTP ${res.status}`);
				const retryable = res.status === 408 || res.status === 429 || res.status >= 500;
				if (!retryable) {
					this.dropped += batch.length;
					return true; // permanently rejected (bad key/payload) — don't retry forever
				}
			} catch (error) {
				this.lastError = error instanceof Error ? error.message : String(error);
				this.log(`flush failed: ${this.lastError}`);
			}
			await new Promise((resolve) => setTimeout(resolve, 400 * (attempt + 1)));
		}
		return false;
	}

	async shutdown(): Promise<void> {
		if (this.timer) clearTimeout(this.timer);
		this.timer = undefined;
		await this.flush();
	}
}

// ---------------------------------------------------------------------------
// Message conversion helpers (pi messages → PostHog-renderable chat messages)
// ---------------------------------------------------------------------------

function truncateText(text: string, max: number): string {
	if (text.length <= max) return text;
	return `${text.slice(0, max)}… [+${text.length - max} chars]`;
}

function safeStringify(value: unknown): string {
	if (typeof value === "string") return value;
	try {
		return JSON.stringify(value) ?? String(value);
	} catch {
		return String(value);
	}
}

/** Clamp arbitrary structured data for span state properties. */
function clampState(value: unknown, max = MAX_STATE_CHARS): unknown {
	const json = safeStringify(value);
	if (json.length <= max) return value;
	return truncateText(json, max);
}

interface ContentPart {
	type?: string;
	text?: string;
	thinking?: string;
	id?: string;
	name?: string;
	arguments?: unknown;
	[key: string]: unknown;
}

function partsToText(content: unknown, captureThinking: boolean): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return safeStringify(content);
	const chunks: string[] = [];
	for (const part of content as ContentPart[]) {
		if (!part || typeof part !== "object") continue;
		if (part.type === "text" && typeof part.text === "string") {
			chunks.push(part.text);
		} else if (part.type === "thinking" && typeof part.thinking === "string") {
			if (captureThinking) chunks.push(`[thinking]\n${part.thinking}`);
		} else if (part.type === "image") {
			chunks.push("[image]");
		}
	}
	return chunks.join("\n");
}

function toolCallsOf(message: AssistantMessage): Array<Record<string, unknown>> {
	const calls: Array<Record<string, unknown>> = [];
	for (const part of message.content ?? []) {
		if (part && typeof part === "object" && part.type === "toolCall") {
			calls.push({
				id: part.id,
				type: "function",
				function: {
					name: part.name,
					arguments: truncateText(safeStringify(part.arguments ?? {}), MAX_TOOL_ARG_CHARS),
				},
			});
		}
	}
	return calls;
}

/**
 * Convert a pi AgentMessage (user / assistant / toolResult / custom) into an
 * OpenAI-style chat message, which is what PostHog's trace view renders best.
 */
function agentMessageToChat(message: unknown, captureThinking: boolean): Record<string, unknown> | undefined {
	const m = message as { role?: string; [key: string]: unknown };
	if (!m || typeof m !== "object") return undefined;
	switch (m.role) {
		case "user":
			return { role: "user", content: truncateText(partsToText(m.content, false), MAX_MESSAGE_CHARS) };
		case "assistant": {
			const assistant = m as unknown as AssistantMessage;
			const chat: Record<string, unknown> = {
				role: "assistant",
				content: truncateText(partsToText(assistant.content, captureThinking), MAX_MESSAGE_CHARS),
			};
			const toolCalls = toolCallsOf(assistant);
			if (toolCalls.length > 0) chat.tool_calls = toolCalls;
			return chat;
		}
		case "toolResult":
			return {
				role: "tool",
				tool_call_id: m.toolCallId,
				name: m.toolName,
				content: truncateText(partsToText(m.content, false), MAX_MESSAGE_CHARS),
			};
		default: {
			// Custom messages injected by pi extensions/skills.
			const label = typeof m.customType === "string" ? m.customType : (m.role ?? "custom");
			const text = partsToText(m.content, false);
			if (!text) return undefined;
			return { role: "user", content: truncateText(`[pi:${label}] ${text}`, MAX_MESSAGE_CHARS) };
		}
	}
}

function convertContext(messages: unknown[], captureThinking: boolean): Array<Record<string, unknown>> {
	const chat = messages
		.map((m) => agentMessageToChat(m, captureThinking))
		.filter((m): m is Record<string, unknown> => m !== undefined);
	if (chat.length <= MAX_INPUT_MESSAGES) return chat;
	const head = chat.slice(0, 2);
	const tail = chat.slice(-(MAX_INPUT_MESSAGES - 3));
	return [
		...head,
		{ role: "user", content: `[pi-posthog: ${chat.length - head.length - tail.length} middle messages omitted]` },
		...tail,
	];
}

function firstLine(text: string, max = 80): string {
	const line = text.split("\n", 1)[0]?.trim() ?? "";
	return line.length > max ? `${line.slice(0, max)}…` : line;
}

// ---------------------------------------------------------------------------
// Extension
// ---------------------------------------------------------------------------

export default function (pi: ExtensionAPI) {
	let cfg = loadConfig(process.cwd());
	let client: PostHogClient | undefined;
	let distinctId = cfg.distinctId ?? defaultDistinctId();
	let sessionId = "";

	// Trace (one per prompt → agent-loop run)
	let traceId: string | undefined;
	let lastTraceId: string | undefined;
	let traceStartMs = 0;
	let tracePrompt = "";
	let turnIndex = 0;
	let generationCount = 0;
	let toolCallCount = 0;
	let lastModel: string | undefined;
	let backgroundTraceId: string | undefined;

	// Current generation (assistant message being streamed)
	let genId: string | undefined;
	let genStartMs = 0;
	let genFirstTokenMs: number | undefined;
	let lastHttpStatus: number | undefined;
	let pendingInput: Array<Record<string, unknown>> | undefined;
	let toolsSnapshot: Array<Record<string, unknown>> | undefined;

	/** toolCallId → span id of the generation that issued the call. */
	const toolOwner = new Map<string, string>();
	const toolStart = new Map<string, { startMs: number; args: unknown }>();

	const debugLogPath = path.join(os.homedir(), ".pi", "agent", "posthog-debug.log");
	const log = (message: string): void => {
		if (!cfg.debug) return;
		try {
			fs.appendFileSync(debugLogPath, `[${new Date().toISOString()}] ${message}\n`);
		} catch {
			/* best effort */
		}
	};

	function initClient(): void {
		if (!cfg.enabled || !cfg.apiKey) {
			client = undefined;
			return;
		}
		client ??= new PostHogClient(cfg, log);
	}

	function updateStatus(ctx: ExtensionContext): void {
		if (!ctx.hasUI || !cfg.statusBar) return;
		try {
			ctx.ui.setStatus("posthog", client ? `posthog ${client.sent + client.queued}` : undefined);
		} catch {
			/* status bar unavailable in this mode */
		}
	}

	function capture(event: string, properties: Record<string, unknown>, ctx?: ExtensionContext): void {
		if (!client || !cfg.enabled) return;
		const props: Record<string, unknown> = {
			$lib: LIB_NAME,
			$lib_version: LIB_VERSION,
			pi_session_id: sessionId,
		};
		for (const [key, value] of Object.entries(properties)) {
			if (value !== undefined) props[key] = value;
		}
		// Keep single events well under PostHog's payload limits: shed heavy
		// properties first rather than dropping the event.
		for (const heavyKey of ["$ai_input", "$ai_output_choices", "$ai_input_state", "$ai_output_state"]) {
			if (safeStringify(props).length <= MAX_EVENT_JSON_CHARS) break;
			if (heavyKey in props) props[heavyKey] = "[pi-posthog: truncated, payload too large]";
		}
		client.capture(event, distinctId, props);
		if (ctx) updateStatus(ctx);
	}

	/** Trace id for LLM calls that happen outside a prompt run (rare). */
	function ensureTraceId(): string {
		if (traceId) return traceId;
		if (!backgroundTraceId) {
			backgroundTraceId = randomUUID();
			capture("$ai_trace", {
				$ai_trace_id: backgroundTraceId,
				$ai_session_id: sessionId,
				$ai_span_name: "pi background",
			});
		}
		return backgroundTraceId;
	}

	// ---- session lifecycle --------------------------------------------------

	pi.on("session_start", async (_event, ctx) => {
		cfg = loadConfig(ctx.cwd);
		distinctId = cfg.distinctId ?? defaultDistinctId();
		initClient();
		sessionId = ctx.sessionManager.getSessionId();
		traceId = undefined;
		backgroundTraceId = undefined;
		toolOwner.clear();
		toolStart.clear();
		log(`session_start session=${sessionId} enabled=${Boolean(client)} host=${cfg.host}`);
		updateStatus(ctx);
	});

	pi.on("session_shutdown", async () => {
		log("session_shutdown — flushing");
		await client?.shutdown();
	});

	// ---- trace lifecycle (one trace per prompt run) --------------------------

	pi.on("before_agent_start", async (event) => {
		tracePrompt = event.prompt ?? "";
	});

	pi.on("agent_start", async () => {
		traceId = randomUUID();
		lastTraceId = traceId;
		traceStartMs = Date.now();
		turnIndex = 0;
		generationCount = 0;
		toolCallCount = 0;
		toolOwner.clear();
		toolStart.clear();
		if (cfg.captureTools) {
			try {
				const active = new Set(pi.getActiveTools());
				toolsSnapshot = pi
					.getAllTools()
					.filter((tool) => active.has(tool.name))
					.map((tool) => ({
						type: "function",
						function: { name: tool.name, description: truncateText(tool.description ?? "", 300) },
					}));
			} catch {
				toolsSnapshot = undefined;
			}
		}
		log(`agent_start trace=${traceId}`);
	});

	pi.on("turn_start", async (event) => {
		turnIndex = event.turnIndex;
	});

	pi.on("context", async (event) => {
		pendingInput = cfg.captureContent ? convertContext(event.messages, cfg.captureThinking) : undefined;
	});

	pi.on("after_provider_response", async (event) => {
		lastHttpStatus = event.status;
	});

	// ---- generations ($ai_generation per LLM call) ---------------------------

	pi.on("message_start", async (event) => {
		if ((event.message as { role?: string }).role !== "assistant") return;
		genId = randomUUID();
		genStartMs = Date.now();
		genFirstTokenMs = undefined;
	});

	pi.on("message_update", async (event) => {
		if (genFirstTokenMs !== undefined) return;
		const type = event.assistantMessageEvent?.type;
		if (type === "text_start" || type === "thinking_start" || type === "toolcall_start") {
			genFirstTokenMs = Date.now();
		}
	});

	pi.on("message_end", async (event, ctx) => {
		const message = event.message as { role?: string };
		if (message.role !== "assistant") return;
		const m = event.message as AssistantMessage;
		const now = Date.now();
		const spanId = genId ?? randomUUID();
		const currentTraceId = ensureTraceId();
		generationCount++;
		lastModel = m.model;

		// Remember which generation issued each tool call so tool spans nest
		// under it in the trace tree.
		for (const part of m.content ?? []) {
			if (part && typeof part === "object" && part.type === "toolCall") {
				toolOwner.set(part.id, spanId);
			}
		}

		const usage = m.usage;
		const isError = m.stopReason === "error" || m.stopReason === "aborted";
		const props: Record<string, unknown> = {
			$ai_trace_id: currentTraceId,
			$ai_span_id: spanId,
			$ai_parent_id: currentTraceId,
			$ai_span_name: `turn ${turnIndex}`,
			$ai_session_id: sessionId,
			$ai_model: m.model,
			$ai_provider: m.provider,
			$ai_base_url: ctx.model?.baseUrl,
			$ai_stream: true,
			$ai_http_status: lastHttpStatus,
			$ai_stop_reason: m.stopReason,
			$ai_input_tokens: usage?.input ?? 0,
			$ai_output_tokens: usage?.output ?? 0,
			$ai_cache_read_input_tokens: usage?.cacheRead ?? 0,
			$ai_cache_creation_input_tokens: usage?.cacheWrite ?? 0,
			$ai_reasoning_tokens: usage?.reasoning,
			$ai_latency: (now - (genStartMs || now)) / 1000,
			$ai_time_to_first_token: [REDACTED] !== undefined ? (genFirstTokenMs - genStartMs) / 1000 : undefined,
			$ai_is_error: isError || undefined,
			$ai_error: isError ? (m.errorMessage ?? m.stopReason) : undefined,
			$ai_tools: toolsSnapshot,
			pi_turn_index: turnIndex,
			pi_api: m.api,
		};

		try {
			props.$ai_model_parameters = { thinking_level: pi.getThinkingLevel() };
		} catch {
			/* not bound yet */
		}

		// pi already computed cost from its model registry — pass it through so
		// PostHog skips its own model lookup (source: "passthrough"). When pi has
		// no pricing (cost 0), omit so PostHog computes from $ai_model instead.
		const cost = usage?.cost;
		if (cost && cost.total > 0) {
			props.$ai_input_cost_usd = cost.input + cost.cacheRead + cost.cacheWrite;
			props.$ai_output_cost_usd = cost.output;
			props.$ai_total_cost_usd = cost.total;
		}
		// Anthropic-style usage reports input tokens exclusive of cache tokens.
		if (m.api === "anthropic-messages") {
			props.$ai_cache_reporting_exclusive = true;
		}

		if (cfg.captureContent) {
			props.$ai_input = pendingInput;
			props.$ai_output_choices = [agentMessageToChat(m, cfg.captureThinking)];
		}

		capture("$ai_generation", props, ctx);
		genId = undefined;
	});

	// ---- tool executions ($ai_span per tool call) -----------------------------

	pi.on("tool_execution_start", async (event) => {
		toolStart.set(event.toolCallId, { startMs: Date.now(), args: event.args });
		toolCallCount++;
	});

	pi.on("tool_execution_end", async (event, ctx) => {
		const started = toolStart.get(event.toolCallId);
		toolStart.delete(event.toolCallId);
		const now = Date.now();
		const result = event.result as { content?: unknown } | undefined;
		const outputText = truncateText(partsToText(result?.content ?? result, false), MAX_STATE_CHARS);
		capture(
			"$ai_span",
			{
				$ai_trace_id: ensureTraceId(),
				$ai_span_id: event.toolCallId,
				$ai_parent_id: toolOwner.get(event.toolCallId) ?? traceId,
				$ai_span_name: event.toolName,
				$ai_span_type: "tool",
				$ai_session_id: sessionId,
				$ai_input_state: cfg.captureContent ? clampState(started?.args) : undefined,
				$ai_output_state: cfg.captureContent ? outputText : undefined,
				$ai_latency: started ? (now - started.startMs) / 1000 : undefined,
				$ai_is_error: event.isError || undefined,
				$ai_error: event.isError ? outputText.slice(0, 1_000) : undefined,
				pi_tool_name: event.toolName,
			},
			ctx,
		);
	});

	// ---- trace close ----------------------------------------------------------

	pi.on("agent_end", async (event, ctx) => {
		if (!traceId) return;
		const messages = event.messages ?? [];
		let finalAssistant: AssistantMessage | undefined;
		for (let i = messages.length - 1; i >= 0; i--) {
			if ((messages[i] as { role?: string }).role === "assistant") {
				finalAssistant = messages[i] as AssistantMessage;
				break;
			}
		}
		const isError = finalAssistant?.stopReason === "error" || finalAssistant?.stopReason === "aborted";
		capture(
			"$ai_trace",
			{
				$ai_trace_id: traceId,
				$ai_session_id: sessionId,
				$ai_span_name: cfg.captureContent ? firstLine(tracePrompt) || "pi run" : "pi run",
				$ai_input_state: cfg.captureContent
					? [{ role: "user", content: truncateText(tracePrompt, MAX_MESSAGE_CHARS) }]
					: undefined,
				$ai_output_state:
					cfg.captureContent && finalAssistant
						? [agentMessageToChat(finalAssistant, cfg.captureThinking)]
						: undefined,
				$ai_latency: (Date.now() - traceStartMs) / 1000,
				$ai_is_error: isError || undefined,
				$ai_error: isError ? (finalAssistant?.errorMessage ?? finalAssistant?.stopReason) : undefined,
				pi_turns: turnIndex + 1,
				pi_generations: generationCount,
				pi_tool_calls: toolCallCount,
				pi_model: lastModel,
			},
			ctx,
		);
		traceId = undefined;
		void client?.flush();
	});

	// ---- compaction -----------------------------------------------------------

	pi.on("session_compact", async (event, ctx) => {
		const parentTrace = traceId ?? lastTraceId;
		if (!parentTrace) return;
		capture(
			"$ai_span",
			{
				$ai_trace_id: parentTrace,
				$ai_span_id: randomUUID(),
				$ai_parent_id: parentTrace,
				$ai_span_name: "compaction",
				$ai_span_type: "compaction",
				$ai_session_id: sessionId,
				$ai_output_state: { reason: event.reason, willRetry: event.willRetry },
			},
			ctx,
		);
	});

	// ---- /posthog command -----------------------------------------------------

	pi.registerCommand("posthog", {
		description: "PostHog LLM analytics — status, or: /posthog flush | test | on | off",
		handler: async (args, ctx) => {
			const arg = args.trim().toLowerCase();
			if (arg === "on" || arg === "off") {
				cfg.enabled = arg === "on";
				if (cfg.enabled) initClient();
				if (cfg.enabled && !client) {
					ctx.ui.notify("posthog enabled, but no API key configured — set PI_POSTHOG_API_KEY", "warning");
				} else {
					ctx.ui.notify(`posthog capture ${cfg.enabled ? "enabled" : "disabled"}`, "info");
				}
				updateStatus(ctx);
				return;
			}
			if (!client) {
				ctx.ui.notify(
					"posthog is not configured — set PI_POSTHOG_API_KEY (or POSTHOG_API_KEY), " +
						"or add { \"apiKey\": \"phc_…\" } to ~/.pi/agent/posthog.json",
					"warning",
				);
				return;
			}
			if (arg === "flush") {
				await client.flush();
				ctx.ui.notify(
					client.lastError ? `posthog flush failed: ${client.lastError}` : `posthog flushed (${client.sent} sent)`,
					client.lastError ? "error" : "info",
				);
				return;
			}
			if (arg === "test") {
				client.capture("pi_posthog_connection_test", distinctId, {
					$lib: LIB_NAME,
					$lib_version: LIB_VERSION,
					pi_session_id: sessionId,
				});
				await client.flush();
				ctx.ui.notify(
					client.lastError
						? `posthog test failed: ${client.lastError}`
						: `posthog test event sent to ${cfg.host}`,
					client.lastError ? "error" : "info",
				);
				return;
			}
			const parts = [
				cfg.enabled ? "enabled" : "disabled",
				`host ${cfg.host}`,
				`distinct_id ${distinctId}`,
				`sent ${client.sent}`,
				`queued ${client.queued}`,
				`dropped ${client.dropped}`,
			];
			if (client.lastError) parts.push(`last error: ${client.lastError}`);
			if (!cfg.captureContent) parts.push("content capture OFF");
			ctx.ui.notify(`posthog · ${parts.join(" · ")}`, client.lastError ? "warning" : "info");
		},
	});
}
